CREATE TRIGGER admission_resources_update BEFORE UPDATE ON resources BEGIN
INSERT INTO admission_resource_uris(uri) SELECT DISTINCT uri FROM (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri UNION ALL SELECT NEW.target AS target, NEW.ksuid AS ksuid, NEW.stack AS stack, NEW.data AS data, NEW.uri AS uri) affected WHERE 1=1 ON CONFLICT(uri) DO NOTHING;
INSERT INTO admission_revisions(guard_key,revision) SELECT u.guard_key,1 FROM admission_resource_uris u JOIN (SELECT DISTINCT uri FROM (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri UNION ALL SELECT NEW.target AS target, NEW.ksuid AS ksuid, NEW.stack AS stack, NEW.data AS data, NEW.uri AS uri) affected) a ON a.uri=u.uri WHERE 1=1 ORDER BY u.guard_key ON CONFLICT(guard_key) DO UPDATE SET revision=revision+1;
INSERT INTO admission_inventory_targets(label) SELECT DISTINCT label FROM (SELECT r.target AS label FROM (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri UNION ALL SELECT NEW.target AS target, NEW.ksuid AS ksuid, NEW.stack AS stack, NEW.data AS data, NEW.uri AS uri) r UNION SELECT json_extract(CASE WHEN json_valid(r.data) THEN r.data ELSE '{}' END, '$.Target') FROM (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri UNION ALL SELECT NEW.target AS target, NEW.ksuid AS ksuid, NEW.stack AS stack, NEW.data AS data, NEW.uri AS uri) r UNION SELECT h.target FROM resources h JOIN (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri UNION ALL SELECT NEW.target AS target, NEW.ksuid AS ksuid, NEW.stack AS stack, NEW.data AS data, NEW.uri AS uri) r ON h.uri=r.uri UNION SELECT json_extract(CASE WHEN json_valid(h.data) THEN h.data ELSE '{}' END, '$.Target') FROM resources h JOIN (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri UNION ALL SELECT NEW.target AS target, NEW.ksuid AS ksuid, NEW.stack AS stack, NEW.data AS data, NEW.uri AS uri) r ON h.uri=r.uri) scopes WHERE label IS NOT NULL ON CONFLICT(label) DO NOTHING;
