INSERT INTO admission_stack_labels(label) SELECT DISTINCT label FROM (SELECT r.stack AS label FROM (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri) r UNION SELECT json_extract(CASE WHEN json_valid(r.data) THEN r.data ELSE '{}' END, '$.Stack') FROM (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri) r UNION SELECT h.stack FROM resources h JOIN (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri) r ON h.uri=r.uri UNION SELECT json_extract(CASE WHEN json_valid(h.data) THEN h.data ELSE '{}' END, '$.Stack') FROM resources h JOIN (SELECT OLD.target AS target, OLD.ksuid AS ksuid, OLD.stack AS stack, OLD.data AS data, OLD.uri AS uri) r ON h.uri=r.uri) labels WHERE label IS NOT NULL ON CONFLICT(label) DO NOTHING;
